INSERT INTO transcript_segments VALUES('9-1Padxsmio-320','9-1Padxsmio',704.5190000000000054,3.879999999999999894,unistr('And last but not least,\u000awe''re gonna warm up the soul.'),320);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-321','9-1Padxsmio',708.3990000000000009,1.629999999999999894,unistr('To warm up the soul\u000aI''m going to give you guys'),321);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-322','9-1Padxsmio',710.0289999999999964,1.820999999999999953,'three soul reminders.',322);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-323','9-1Padxsmio',711.8500000000000227,1.65900000000000003,unistr('Soul reminder\u000anumber one...'),323);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-324','9-1Padxsmio',713.5090000000000145,1.310000000000000053,'Singing is a miracle!',324);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-325','9-1Padxsmio',714.81899999999996,2.471000000000000085,unistr('Can you believe that\u000awe can even do this?'),325);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-326','9-1Padxsmio',717.2899999999999637,1.199999999999999956,unistr('These two little\u000avocal cords'),326);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-327','9-1Padxsmio',718.490000000000009,2.979999999999999983,unistr('are going to slap together\u000atens or hundreds of thousands'),327);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-328','9-1Padxsmio',721.4700000000000272,1.080000000000000072,'of times today?',328);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-329','9-1Padxsmio',722.5499999999999546,2.519000000000000127,unistr('To produce all kinds of\u000avocal glory?'),329);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-330','9-1Padxsmio',725.06899999999996,1.939999999999999947,unistr('The fact that this\u000ais even possible'),330);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-331','9-1Padxsmio',727.0090000000000145,2.350000000000000088,unistr('is something that\u000awe can be thankful for.'),331);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-332','9-1Padxsmio',729.3590000000000372,2.450000000000000177,'Wow, I get to sing today.',332);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-333','9-1Padxsmio',731.8089999999999691,1.411000000000000031,'How amazing is that?',333);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-334','9-1Padxsmio',733.2200000000000272,4.480000000000000427,unistr('Not everybody has that possibility\u000ato sing every day.'),334);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-335','9-1Padxsmio',737.7089999999999463,1.770999999999999908,'And you and I do?',335);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-336','9-1Padxsmio',739.4800000000000181,1.429999999999999938,'What a miracle.',336);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-337','9-1Padxsmio',740.9099999999999682,1.0,'Point number two...',337);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-338','9-1Padxsmio',741.9099999999999682,1.679000000000000047,unistr('I can look at my\u000avoice and say'),338);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-339','9-1Padxsmio',743.5890000000000555,2.020999999999999908,unistr('it''s so bad,\u000aI''m so discouraged,'),339);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-340','9-1Padxsmio',745.6100000000000136,2.359999999999999876,unistr('I hate how I sound,\u000aI''m never gonna'),340);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-341','9-1Padxsmio',747.9700000000000272,1.959000000000000074,unistr('be good enough\u000aor make it.'),341);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-342','9-1Padxsmio',749.9289999999999737,1.931000000000000049,unistr('You have that choice,\u000ayou can look at it that way.'),342);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-343','9-1Padxsmio',751.8600000000000136,1.949000000000000065,unistr('Or you can\u000achoose to say...'),343);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-344','9-1Padxsmio',753.8089999999999691,2.529999999999999805,unistr('I''m better at my singing,\u000aI love to sing,'),344);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-345','9-1Padxsmio',756.3390000000000555,3.841000000000000191,unistr('I love what it does for me,\u000aI love to give it away to others,'),345);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-346','9-1Padxsmio',760.17999999999995,2.640000000000000124,unistr('I feel good about\u000amy singing.'),346);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-347','9-1Padxsmio',762.82000000000005,1.0,'That''s your choice.',347);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-348','9-1Padxsmio',763.82000000000005,1.850000000000000088,unistr('You can choose\u000aeither of them,'),348);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-349','9-1Padxsmio',765.6699999999999591,1.758999999999999897,'And point number three...',349);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-350','9-1Padxsmio',767.4289999999999737,1.0,'You look good.',350);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-351','9-1Padxsmio',768.4289999999999737,2.520000000000000017,unistr('Did I tell you\u000athat recently?'),351);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-352','9-1Padxsmio',770.9489999999999555,2.040000000000000035,unistr('You are lookin''\u000areally good.'),352);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-353','9-1Padxsmio',772.9890000000000327,2.5,unistr('You''re lookin'' fit,\u000ayou''re lookin'' like you'),353);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-354','9-1Padxsmio',775.4890000000000327,2.910000000000000142,unistr('got that sparkle,\u000ayou got a twinkle in your eye,'),354);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-355','9-1Padxsmio',778.3990000000000009,1.560000000000000053,'a smile on your face,',355);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-356','9-1Padxsmio',779.9589999999999463,3.359999999999999876,unistr('you just seem like you\u000agot that swagger,'),356);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-357','9-1Padxsmio',783.31899999999996,1.0,'that confidence.',357);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-358','9-1Padxsmio',784.31899999999996,1.580000000000000071,unistr('So I don''t know\u000awhat you''ve been doing'),358);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-359','9-1Padxsmio',785.8990000000000009,2.821000000000000174,unistr('but I want to be the first\u000aperson today to tell you,'),359);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-360','9-1Padxsmio',788.7200000000000272,2.0,unistr('you have got it\u000agoin'' on.'),360);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-361','9-1Padxsmio',790.7200000000000272,2.879999999999999894,unistr('You are lookin''\u000areally, really good.'),361);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-362','9-1Padxsmio',793.6000000000000227,2.508999999999999897,unistr('So those are your\u000asoul reminders for today.'),362);
