INSERT INTO transcript_segments VALUES('9-1Padxsmio-368','9-1Padxsmio',808.17999999999995,4.559000000000000163,'Questions@VoiceLessonsToTheWorld.com.',368);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-369','9-1Padxsmio',812.7390000000000327,2.431000000000000049,unistr('So we just encourage you,\u000adon''t lose that joy,'),369);
INSERT INTO transcript_segments VALUES('9-1Padxsmio-370','9-1Padxsmio',815.1699999999999591,1.209000000000000074,'don''t lose that passion.',370);
