INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-5','oDrhkt8KIA4',26.12999999999999901,2.229999999999999983,unistr('The show where we want to\u000ahelp you as singers'),392);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-6','oDrhkt8KIA4',28.35999999999999944,2.589999999999999858,unistr('by answering your questions\u000afrom all over.'),393);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-7','oDrhkt8KIA4',30.94999999999999929,1.810000000000000053,unistr('And I''ll give you a chance\u000ato ask questions later'),394);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-8','oDrhkt8KIA4',32.75999999999999802,3.040000000000000035,unistr('but our question\u000afor this week comes from'),395);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-9','oDrhkt8KIA4',35.79999999999999715,3.339999999999999858,'Ivo F. in Espinho, Portugal.',396);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-10','oDrhkt8KIA4',39.14000000000000056,4.959999999999999965,unistr('And Ivo writes, "Dear Justin what\u000ais the appoggio breathing technique,'),397);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-11','oDrhkt8KIA4',44.10999999999999944,3.899999999999999912,unistr('and is it as helpful\u000aas everyone says?"'),398);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-12','oDrhkt8KIA4',48.00999999999999802,5.459999999999999965,unistr('Well yes Ivo, yes, I think the\u000aappoggio is pretty great.'),399);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-13','oDrhkt8KIA4',53.46999999999999887,2.490000000000000213,unistr('And that''s what we''re going to\u000abe exploring today.'),400);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-14','oDrhkt8KIA4',55.96000000000000085,4.419999999999999929,unistr('In fact appoggio breathing\u000ais the gold standard'),401);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-15','oDrhkt8KIA4',60.38000000000000255,2.859999999999999876,'of all breathing techniques.',402);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-16','oDrhkt8KIA4',63.24000000000000198,10.43999999999999951,'♬',403);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-17','oDrhkt8KIA4',73.68000000000000683,1.0,'Awesome!',404);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-18','oDrhkt8KIA4',74.90000000000000569,3.819999999999999841,unistr('So what makes the\u000aappoggio the gold standard'),405);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-19','oDrhkt8KIA4',78.72899999999999921,2.620999999999999997,unistr('and what is this\u000aappoggio anyway?'),406);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-20','oDrhkt8KIA4',81.34999999999999431,4.62899999999999956,unistr('Well "appoggio", the word,\u000acomes from the Italian word "appoggiare"'),407);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-21','oDrhkt8KIA4',85.97899999999999921,2.419999999999999929,'which means "to lean".',408);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-22','oDrhkt8KIA4',88.3990000000000009,2.940999999999999837,unistr('So it''s the lean\u000aof the body.'),409);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-23','oDrhkt8KIA4',91.34000000000000341,2.119000000000000217,unistr('With the appoggio we''re\u000amaking sure that'),410);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-24','oDrhkt8KIA4',93.4590000000000031,3.600999999999999979,unistr('our body doesn''t just collapse\u000awhen we breathe.'),411);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-25','oDrhkt8KIA4',97.0600000000000022,5.418999999999999595,unistr('But it sits, leans down,\u000aon the breathing system that we create.'),412);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-26','oDrhkt8KIA4',102.4789999999999993,5.26100000000000012,unistr('We inhale and then we\u000amaintain the position of that inhale.'),413);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-27','oDrhkt8KIA4',107.7399999999999949,4.0,unistr('We do this with a combination\u000aof rib and belly breathing.'),414);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-28','oDrhkt8KIA4',111.7399999999999949,2.709999999999999965,unistr('If you remember back to\u000aepisode 1 of our show'),415);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-29','oDrhkt8KIA4',114.4500000000000028,2.758999999999999897,unistr('we talked about the\u000aprimary breathing types.'),416);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-30','oDrhkt8KIA4',117.2090000000000031,4.600999999999999979,unistr('Well appoggio breathing combines\u000athe belly and the rib breathing'),417);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-31','oDrhkt8KIA4',121.8100000000000022,6.759000000000000341,unistr('into one dual system for your optimal\u000aand gold standard breathing technique.'),418);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-32','oDrhkt8KIA4',128.5689999999999885,4.301000000000000156,unistr('Yes, it will give you the\u000abest breath support.'),419);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-33','oDrhkt8KIA4',132.8700000000000045,3.310000000000000053,unistr('But let''s remind ourselves,\u000awhat is breath support?'),420);
