INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-40','oDrhkt8KIA4',152.7800000000000011,3.23899999999999988,unistr('Well looks like you got to work\u000aon your breath support, my friend.'),427);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-41','oDrhkt8KIA4',156.0190000000000054,4.121000000000000441,unistr('Went to see a concert the other night\u000areally didn''t like that singer too well.'),428);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-42','oDrhkt8KIA4',160.1399999999999863,3.229999999999999983,unistr('Seemed like they could\u000ahave used more support.'),429);
INSERT INTO transcript_segments VALUES('oDrhkt8KIA4-43','oDrhkt8KIA4',163.3700000000000045,2.229000000000000092,unistr('Problem is, if we don''t\u000aknow what that means'),430);
