INSERT INTO transcript_segments VALUES('CYEsGuldIQY-0','CYEsGuldIQY',0.1199999999999999956,16.0,'♬',688);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-1','CYEsGuldIQY',17.03999999999999915,0.8800000000000000044,'Hi everybody!',689);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-2','CYEsGuldIQY',17.92000000000000171,1.879999999999999894,unistr('My name is Justin Stoney\u000aand I''m the founder of'),690);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-3','CYEsGuldIQY',19.80000000000000071,2.359999999999999876,unistr('New York Vocal Coaching\u000ahere in New York City.'),691);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-4','CYEsGuldIQY',22.16000000000000014,2.629999999999999894,unistr('Welcome to episode 40 of\u000aVoice Lessons To The World.'),692);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-5','CYEsGuldIQY',24.78999999999999915,1.699999999999999956,unistr('The show where we want to\u000ahelp you guys as singers'),693);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-6','CYEsGuldIQY',26.48999999999999844,2.049999999999999822,unistr('by answering your\u000aquestions from all over.'),694);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-7','CYEsGuldIQY',28.53999999999999915,1.550000000000000044,unistr('And I''ll give you a chance\u000ato ask questions later'),695);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-8','CYEsGuldIQY',30.08999999999999986,2.390000000000000124,unistr('but our question for this\u000aweek comes from'),696);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-9','CYEsGuldIQY',32.47999999999999687,3.020000000000000017,'Adrianah T. in Haslett, Michigan.',697);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-10','CYEsGuldIQY',35.5,6.820000000000000284,unistr('And Adrianah writes, "Dear Justin\u000awhat is the mix voice and how do I do it?"'),698);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-11','CYEsGuldIQY',43.47999999999999687,3.640000000000000124,unistr('Now Adrianah that''s the question\u000aI think we''ve all been waiting for.'),699);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-12','CYEsGuldIQY',47.11999999999999745,3.330000000000000071,unistr('I get so many questions\u000afrom singers about what is the mix,'),700);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-13','CYEsGuldIQY',50.45000000000000284,3.169999999999999929,unistr('how do I mix,\u000ais this singer doing a mix,'),701);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-14','CYEsGuldIQY',53.61999999999999745,3.149999999999999912,unistr('everybody wants to know\u000ahow to do the mix voice.'),702);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-15','CYEsGuldIQY',56.77000000000000312,1.870000000000000106,unistr('And you should,\u000ait''s totally awesome.'),703);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-16','CYEsGuldIQY',58.64000000000000056,3.029999999999999805,unistr('And we''re going to figure it out\u000atogether today.'),704);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-17','CYEsGuldIQY',61.6700000000000017,2.459999999999999965,unistr('The first thing that we\u000aneed to know though is'),705);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-18','CYEsGuldIQY',64.12999999999999546,1.979999999999999983,'what is a vocal register?',706);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-19','CYEsGuldIQY',66.10999999999999944,2.140000000000000124,unistr('Because the mix is a kind\u000aof vocal register.'),707);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-20','CYEsGuldIQY',68.25,1.679999999999999938,unistr('So we have to know what\u000athat even means.'),708);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-21','CYEsGuldIQY',69.93000000000000683,2.209999999999999965,'A vocal register.',709);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-22','CYEsGuldIQY',72.14000000000000056,1.209999999999999965,unistr('When I''m talking to\u000ayou like this'),710);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-23','CYEsGuldIQY',73.34999999999999431,4.080000000000000071,unistr('I''m talking to you in a\u000avocal register called chest voice.'),711);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-24','CYEsGuldIQY',77.43000000000000683,4.450000000000000177,unistr('But if I talk to you like this I''m\u000atalking to you in another vocal register'),712);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-25','CYEsGuldIQY',81.87999999999999546,2.700000000000000177,'which is called falsetto.',713);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-26','CYEsGuldIQY',84.5799999999999983,1.5,unistr('So I want you guys\u000ato try some of these'),714);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-27','CYEsGuldIQY',86.0799999999999983,2.060000000000000053,'vocal registers with me.',715);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-28','CYEsGuldIQY',88.14000000000000056,2.779999999999999805,unistr('First in your chest voice,\u000aguys and girls just say'),716);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-29','CYEsGuldIQY',90.9200000000000017,2.0,'hello my name is Justin.',717);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-30','CYEsGuldIQY',92.9200000000000017,1.459999999999999965,unistr('Of course use your own\u000aname though.'),718);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-31','CYEsGuldIQY',94.3799999999999955,0.7399999999999999912,'Here we go!',719);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-32','CYEsGuldIQY',96.5,1.219999999999999974,'That was great.',720);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-33','CYEsGuldIQY',97.7199999999999989,3.180000000000000159,unistr('Now in your falsetto,\u000aor women, head voice,'),721);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-34','CYEsGuldIQY',100.9000000000000056,2.520000000000000017,unistr('say,\u000ahello my name is Justin.'),722);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-35','CYEsGuldIQY',105.2800000000000011,1.0,'That''s great!',723);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-36','CYEsGuldIQY',106.2900000000000062,2.080000000000000071,unistr('Good, so you see that\u000adifference between'),724);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-37','CYEsGuldIQY',108.3700000000000045,5.009999999999999787,unistr('a chest voice register\u000aand a head voice or falsetto register.'),725);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-38','CYEsGuldIQY',113.3799999999999955,2.930000000000000159,unistr('Now there''s some other registers\u000athat people sometimes talk about.'),726);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-39','CYEsGuldIQY',116.3100000000000022,2.569999999999999841,unistr('There''s the whistle voice,\u000athat''s way, way up there.'),727);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-40','CYEsGuldIQY',118.8799999999999955,1.800000000000000044,unistr('We might talk about\u000athat another time.'),728);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-41','CYEsGuldIQY',120.6800000000000068,2.399999999999999912,unistr('There''s the fry,\u000athe vocal fry.'),729);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-42','CYEsGuldIQY',123.0799999999999983,2.479999999999999983,unistr('Which is this\u000asound right here.'),730);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-43','CYEsGuldIQY',125.5600000000000022,1.760000000000000008,unistr('We should actually\u000atry that one together.'),731);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-44','CYEsGuldIQY',127.3199999999999932,3.200000000000000177,unistr('Just say,\u000ahello my name is Justin.'),732);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-45','CYEsGuldIQY',130.5200000000000102,1.199999999999999956,'Try that out.',733);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-46','CYEsGuldIQY',132.9799999999999898,2.100000000000000088,'That''s good, great job!',734);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-47','CYEsGuldIQY',135.0800000000000125,1.840000000000000079,unistr('So those are all\u000avocal registers.'),735);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-48','CYEsGuldIQY',136.9199999999999875,4.200000000000000177,unistr('And now the mix is a\u000akind of vocal register.'),736);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-49','CYEsGuldIQY',141.1200000000000045,1.330000000000000071,unistr('It''s actually more\u000athan one thing'),737);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-50','CYEsGuldIQY',142.4499999999999887,1.989999999999999992,unistr('which is why people\u000aget confused about it.'),738);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-51','CYEsGuldIQY',144.4399999999999978,4.36000000000000032,unistr('It''s not just one mix,\u000abut it''s some blend between'),739);
