INSERT INTO transcript_segments VALUES('CYEsGuldIQY-53','CYEsGuldIQY',152.8400000000000034,2.140000000000000124,unistr('that you guys\u000aalready felt.'),741);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-54','CYEsGuldIQY',154.9799999999999898,1.780000000000000026,unistr('So what I''m going to do\u000afor you right now'),742);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-55','CYEsGuldIQY',156.759999999999991,3.700000000000000177,unistr('is do in my speaking voice\u000aa really smooth transition'),743);
