INSERT INTO transcript_segments VALUES('CYEsGuldIQY-57','CYEsGuldIQY',163.0600000000000022,2.810000000000000053,unistr('a bunch of mixes\u000aand then into my chest voice.'),745);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-58','CYEsGuldIQY',165.8700000000000045,4.599999999999999644,unistr('So you guys really can get\u000ain your ear what a mix sounds like'),746);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-59','CYEsGuldIQY',170.4699999999999989,1.889999999999999903,'just in my speaking voice.',747);
