INSERT INTO transcript_segments VALUES('CYEsGuldIQY-135','CYEsGuldIQY',334.5690000000000168,3.391000000000000014,unistr('What''s the missing ingredient\u000ato making that mix work?'),823);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-136','CYEsGuldIQY',337.9599999999999796,3.540000000000000035,unistr('Here''s the thing that nobody will\u000atell you and is really the truth.'),824);
INSERT INTO transcript_segments VALUES('CYEsGuldIQY-137','CYEsGuldIQY',342.240000000000009,1.540000000000000035,'The mix is two things.',825);
