INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-7','2eSbUlbLTKw',31.85999999999999944,1.719999999999999974,unistr('And I''ll give you a chance\u000ato ask questions later,'),1388);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-8','2eSbUlbLTKw',33.5799999999999983,4.879999999999999894,unistr('but our question for this week comes\u000afrom Daniel S. from Queensland, Australia.'),1389);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-9','2eSbUlbLTKw',38.46000000000000085,3.700000000000000177,unistr('And if you remember last week, \u000aDaniel was asking about how'),1390);
