INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-20','2eSbUlbLTKw',76.79999999999999716,2.680000000000000159,unistr('It''s the sort of\u000a♪ Yodel-ay-hee-hoo ♪'),1401);
