INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-96','2eSbUlbLTKw',290.9599999999999796,2.660000000000000142,'♪ OO - OO - OO - OO - OO ♪',1477);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-97','2eSbUlbLTKw',293.6200000000000045,1.120000000000000107,'♪',1478);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-98','2eSbUlbLTKw',295.0600000000000022,1.300000000000000044,'Great stuff!',1479);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-99','2eSbUlbLTKw',296.3600000000000136,1.919999999999999929,'So that''s a yodel exercise.',1480);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-100','2eSbUlbLTKw',298.2799999999999727,2.620000000000000106,unistr('Again, it''s kind of weird,\u000ait''s kind of goofy.'),1481);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-101','2eSbUlbLTKw',300.8999999999999773,3.589999999999999858,unistr('But think about it, isn''t it \u000aactually kind of weird how'),1482);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-102','2eSbUlbLTKw',304.490000000000009,3.390000000000000124,unistr('Adele goes so fast up \u000ato head voice like that?'),1483);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-103','2eSbUlbLTKw',307.8799999999999955,1.447999999999999954,'I mean it sounds awesome.',1484);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-104','2eSbUlbLTKw',309.3279999999999746,2.721999999999999976,unistr('But it actually really is a\u000acrack of the voice.'),1485);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-105','2eSbUlbLTKw',312.0500000000000113,3.490000000000000213,unistr('It''s kind of a yodel-y sound,\u000ait''s just that when Adele does it'),1486);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-106','2eSbUlbLTKw',315.5400000000000204,3.080000000000000071,unistr('in the context of her great songs, \u000ait sounds totally awesome.'),1487);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-107','2eSbUlbLTKw',318.6200000000000045,2.020000000000000017,'But really, it''s yodeling.',1488);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-108','2eSbUlbLTKw',320.6399999999999864,4.620000000000000106,unistr('And so if we have an exercise like that\u000awe can we can do a lot of things.'),1489);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-109','2eSbUlbLTKw',325.259999999999991,3.399999999999999912,unistr('Let me just talk about the benefits\u000aof doing something like that.'),1490);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-110','2eSbUlbLTKw',329.3799999999999955,3.819999999999999841,unistr('First of all, like I say, you get to do the\u000acool tricks that Adele does in her songs.'),1491);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-111','2eSbUlbLTKw',333.1999999999999887,4.179999999999999715,unistr('But also, the vocal cords \u000anaturally want to stretch out'),1492);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-112','2eSbUlbLTKw',337.3799999999999955,2.160000000000000143,unistr('and lengthen and\u000aseparate like that.'),1493);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-113','2eSbUlbLTKw',339.5400000000000204,3.229999999999999983,unistr('So it''s really good for \u000ayour voice to do that.'),1494);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-114','2eSbUlbLTKw',342.7699999999999819,3.410000000000000142,unistr('It''s allowing the cords to \u000ado their natural function.'),1495);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-115','2eSbUlbLTKw',346.1899999999999978,3.009999999999999787,unistr('They just want to have \u000athat kind of flexibility.'),1496);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-116','2eSbUlbLTKw',349.1999999999999887,2.399999999999999912,unistr('They want to crack\u000aas you go higher.'),1497);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-117','2eSbUlbLTKw',351.6000000000000227,4.599999999999999644,unistr('So by allowing that you''re really\u000abuilding in some flexibility to your voice.'),1498);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-118','2eSbUlbLTKw',356.1999999999999887,3.100000000000000088,unistr('Now flexibility will also\u000alead to better agility.'),1499);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-119','2eSbUlbLTKw',359.8600000000000136,3.580000000000000071,unistr('And so you''ll find that by doing\u000athis you''ll be able to move faster,'),1500);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-120','2eSbUlbLTKw',363.4399999999999978,6.339999999999999858,unistr('your riffs will get better, you''ll \u000abe able to probably sing higher notes, period,'),1501);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-121','2eSbUlbLTKw',369.7799999999999727,1.419999999999999929,'due to greater flexibility.',1502);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-122','2eSbUlbLTKw',371.1999999999999887,2.290000000000000035,unistr('And it can also improve\u000ayour vibrato.'),1503);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-123','2eSbUlbLTKw',373.490000000000009,3.490000000000000213,unistr('So there''s tons of reasons\u000awhy allowing the voice to do that,'),1504);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-124','2eSbUlbLTKw',376.9800000000000181,3.080000000000000071,unistr('to crack and to go\u000aback and forth like that,'),1505);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-125','2eSbUlbLTKw',380.0600000000000022,4.13999999999999968,unistr('is actually a really healthy thing\u000aand is a skill builder as well.'),1506);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-126','2eSbUlbLTKw',384.6200000000000045,3.859999999999999876,unistr('And then finally another benefit to\u000ayodeling is attracting sheep.'),1507);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-127','2eSbUlbLTKw',389.0,1.844000000000000083,unistr('I''m sure that if you do\u000athis exercise enough'),1508);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-128','2eSbUlbLTKw',390.8439999999999941,3.056000000000000049,unistr('there''s going to be hordes of \u000asheep coming to your door.'),1509);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-129','2eSbUlbLTKw',393.8999999999999773,4.080000000000000071,unistr('And if you if you do it well you''re\u000agoing to increase your flocks,'),1510);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-130','2eSbUlbLTKw',397.9800000000000181,3.0,unistr('and you''re going to have an\u000aabundance of sheep as well.'),1511);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-131','2eSbUlbLTKw',401.5799999999999841,2.919999999999999929,unistr('So, obviously,\u000athat''s just a joke.'),1512);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-132','2eSbUlbLTKw',404.5,3.660000000000000142,unistr('But, I do think that yodeling\u000ais going to be something that'),1513);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-133','2eSbUlbLTKw',408.1689999999999828,2.717000000000000081,unistr('can really help you,\u000aas strange as it may be,'),1514);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-134','2eSbUlbLTKw',410.8860000000000241,3.37300000000000022,unistr('to develop some of these\u000acoordinations in your voice.'),1515);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-135','2eSbUlbLTKw',414.2590000000000145,3.181000000000000049,unistr('So Daniel and all, I hope that''s\u000abeen helpful for you guys today.'),1516);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-136','2eSbUlbLTKw',417.4399999999999978,2.859999999999999876,unistr('If you have questions that you''d\u000alike to see us answer on the show\u000a[♪]'),1517);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-137','2eSbUlbLTKw',420.3000000000000113,5.379999999999999894,unistr('you can send an email to: Questions@VoiceLessonsToTheWorld.com\u000a[♪]'),1518);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-138','2eSbUlbLTKw',425.6800000000000068,3.770000000000000017,unistr('So we just encourage you not to\u000alose that joy, don''t lose that passion.\u000a[♪]'),1519);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-139','2eSbUlbLTKw',429.4499999999999887,3.549999999999999823,unistr('Don''t be afraid to experiment with\u000aweird and goofy things like yodeling.\u000a[♪]'),1520);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-140','2eSbUlbLTKw',433.0,2.004999999999999894,unistr('I just know that if you work\u000aon something like that,\u000a[♪]'),1521);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-141','2eSbUlbLTKw',435.0049999999999955,2.274999999999999912,unistr('it''s going to give you some new\u000acoordinations in your voice\u000a[♪]'),1522);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-142','2eSbUlbLTKw',437.2799999999999727,1.840000000000000079,unistr('that you never\u000athought were possible.\u000a[♪]'),1523);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-143','2eSbUlbLTKw',439.1200000000000045,1.840000000000000079,unistr('Get with a great voice\u000ateacher in your area.\u000a[♪]'),1524);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-144','2eSbUlbLTKw',440.9700000000000273,1.991000000000000103,unistr('If you guys are in \u000aNew York City\u000a[♪]'),1525);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-145','2eSbUlbLTKw',442.9610000000000127,3.73899999999999988,unistr('you can check us out at:  www.NewYorkVocalCoaching.com\u000a[♪]'),1526);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-146','2eSbUlbLTKw',446.6999999999999887,2.660000000000000142,unistr('And if you like these \u000avideos you can visit:\u000a[♪]'),1527);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-147','2eSbUlbLTKw',449.3600000000000136,2.640000000000000124,unistr('www.VoiceLessonsToTheWorld.com\u000a[♪]'),1528);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-148','2eSbUlbLTKw',452.0,1.324000000000000065,unistr('I''m Justin Stoney.\u000a[♪]'),1529);
INSERT INTO transcript_segments VALUES('2eSbUlbLTKw-149','2eSbUlbLTKw',453.3240000000000122,1.556000000000000049,unistr('We''ll see you next time.\u000a[♪]'),1530);
